"use client";
import React, { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/components/auth/auth-context";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Spinner } from "@/components/ui/spinner";
import UsersManagement from "@/components/admin/users-management";
import ArticlesManagement from "@/components/admin/articles-management";
import TicketsManagement from "@/components/admin/tickets-management";
import MedicinesManagement from "@/components/admin/medicines-management";
import ReviewsManagement from "@/components/admin/reviews-management";
import {
  Users,
  FileText,
  Headphones,
  Pill,
  Star,
  BarChart3,
  Shield,
} from "lucide-react";

export default function AdminPage() {
  const router = useRouter();
  const { user, loading: authLoading } = useAuth();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    console.log("Admin page - authLoading:", authLoading, "user:", user);

    if (authLoading) return;

    if (!user) {
      console.log("No user found, redirecting to login");
      router.push("/auth/login");
      return;
    }

    console.log("User role:", user.role);

    // Check if user has admin role
    if (user.role !== "admin") {
      console.log("User is not admin, redirecting to dashboard");
      router.push("/dashboard");
      return;
    }

    console.log("Admin access granted");
    setLoading(false);
  }, [user, authLoading, router]);

  if (authLoading || loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-100 via-slate-50 to-purple-50">
        {/* Dark header skeleton */}
        <div className="bg-gradient-to-r from-slate-900 via-slate-800 to-slate-900 py-8 px-4">
          <div className="max-w-7xl mx-auto">
            <div className="animate-pulse">
              <div className="h-8 w-48 bg-slate-700 rounded mb-4"></div>
              <div className="h-6 w-64 bg-slate-700 rounded"></div>
            </div>
          </div>
        </div>
        <div className="max-w-7xl mx-auto py-8 px-4">
          <div className="flex items-center justify-center py-20">
            <Spinner className="h-8 w-8" />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-100 via-slate-50 to-purple-50">
      {/* Dark Hero Header */}
      <div className="bg-gradient-to-r from-slate-900 via-slate-800 to-slate-900 py-8 px-4">
        <div className="max-w-7xl mx-auto">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 rounded-xl bg-purple-500/20 border border-purple-500/30 flex items-center justify-center">
              <Shield className="w-7 h-7 text-purple-400" />
            </div>
            <div>
              <h1 className="text-3xl font-bold text-white">Admin Dashboard</h1>
              <p className="text-slate-400 mt-1">
                Manage users, content, support tickets, and more
              </p>
            </div>
          </div>

          {/* Quick Stats */}
          <div className="grid grid-cols-5 gap-4 mt-8">
            <div className="bg-white/5 border border-white/10 rounded-xl p-4 text-center">
              <Users className="h-6 w-6 text-indigo-400 mx-auto mb-2" />
              <p className="text-white font-semibold">Users</p>
            </div>
            <div className="bg-white/5 border border-white/10 rounded-xl p-4 text-center">
              <FileText className="h-6 w-6 text-blue-400 mx-auto mb-2" />
              <p className="text-white font-semibold">Articles</p>
            </div>
            <div className="bg-white/5 border border-white/10 rounded-xl p-4 text-center">
              <Headphones className="h-6 w-6 text-purple-400 mx-auto mb-2" />
              <p className="text-white font-semibold">Tickets</p>
            </div>
            <div className="bg-white/5 border border-white/10 rounded-xl p-4 text-center">
              <Pill className="h-6 w-6 text-teal-400 mx-auto mb-2" />
              <p className="text-white font-semibold">Medicines</p>
            </div>
            <div className="bg-white/5 border border-white/10 rounded-xl p-4 text-center">
              <Star className="h-6 w-6 text-amber-400 mx-auto mb-2" />
              <p className="text-white font-semibold">Reviews</p>
            </div>
          </div>
        </div>
      </div>

      {/* Content */}
      <div className="max-w-7xl mx-auto py-8 px-4">
        <Tabs defaultValue="users" className="space-y-6">
          <TabsList className="grid w-full grid-cols-5 lg:w-auto bg-white border border-slate-200 p-1 rounded-lg shadow-sm">
            <TabsTrigger value="users" className="flex items-center gap-2 data-[state=active]:bg-slate-800 data-[state=active]:text-white">
              <Users className="h-4 w-4 text-indigo-500 data-[state=active]:text-indigo-300" />
              <span className="hidden sm:inline">Users</span>
            </TabsTrigger>
            <TabsTrigger value="articles" className="flex items-center gap-2 data-[state=active]:bg-slate-800 data-[state=active]:text-white">
              <FileText className="h-4 w-4 text-blue-500 data-[state=active]:text-blue-300" />
              <span className="hidden sm:inline">Articles</span>
            </TabsTrigger>
            <TabsTrigger value="tickets" className="flex items-center gap-2 data-[state=active]:bg-slate-800 data-[state=active]:text-white">
              <Headphones className="h-4 w-4 text-purple-500 data-[state=active]:text-purple-300" />
              <span className="hidden sm:inline">Tickets</span>
            </TabsTrigger>
            <TabsTrigger value="medicines" className="flex items-center gap-2 data-[state=active]:bg-slate-800 data-[state=active]:text-white">
              <Pill className="h-4 w-4 text-teal-500 data-[state=active]:text-teal-300" />
              <span className="hidden sm:inline">Medicines</span>
            </TabsTrigger>
            <TabsTrigger value="reviews" className="flex items-center gap-2 data-[state=active]:bg-slate-800 data-[state=active]:text-white">
              <Star className="h-4 w-4 text-amber-500 data-[state=active]:text-amber-300" />
              <span className="hidden sm:inline">Reviews</span>
            </TabsTrigger>
          </TabsList>

          <TabsContent value="users">
            <UsersManagement />
          </TabsContent>

          <TabsContent value="articles">
            <ArticlesManagement />
          </TabsContent>

          <TabsContent value="tickets">
            <TicketsManagement />
          </TabsContent>

          <TabsContent value="medicines">
            <MedicinesManagement />
          </TabsContent>

          <TabsContent value="reviews">
            <ReviewsManagement />
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}
